/**
 * Cloudflare Workers entry (wrangler.jsonc "main"). Serves the OpenNext build and adds
 * the Cron Trigger that the Node deployment gets from an external scheduler: every ten
 * minutes it runs the maintenance job (notification retries, pruning, reminders).
 */
// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- the import exists only after a build, so expect-error would fail afterwards
// @ts-ignore: generated by `opennextjs-cloudflare build`
import { default as handler } from "../.open-next/worker.js";

type Env = { APP_URL?: string; CRON_SECRET?: string };
type Ctx = { waitUntil(promise: Promise<unknown>): void };
type Fetch = (request: Request, env: Env, ctx: Ctx) => Promise<Response>;

const worker = {
  fetch: handler.fetch as Fetch,

  async scheduled(_controller: unknown, env: Env, ctx: Ctx) {
    if (!env.CRON_SECRET) return;
    const url = new URL("/api/cron/maintenance", env.APP_URL ?? "https://localhost");
    const request = new Request(url, { method: "POST", headers: { authorization: `Bearer ${env.CRON_SECRET}` } });
    ctx.waitUntil(
      (handler.fetch as Fetch)(request, env, ctx).then(async (res) => {
        if (!res.ok) console.error("maintenance cron failed", res.status, await res.text());
      }),
    );
  },
};

export default worker;

// Durable Object used by the revalidation queue (open-next.config.ts).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment -- the import exists only after a build, so expect-error would fail afterwards
// @ts-ignore: generated by `opennextjs-cloudflare build`
export { DOQueueHandler } from "../.open-next/worker.js";
